INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_001', 'single', 'Która frakcja skrobi odpowiada głównie za kleistość ryżu japońskiego?', 'Amylopektyna — rozgałęziona cząsteczka, której ryż japonica ma dużo; nadaje kleistość i słabo retrograduje. Amyloza (liniowa) sprzyja sypkości i twardnieniu w chłodzie.', 1, 'cat_ryz', 'les_ryz_v1_01', 'needs_verification', 'src_claude_academy_v1');
