INSERT INTO search_index (entity_type, entity_id, owner_id, title, body, folded) VALUES ('question', 'q_v1_001', NULL, 'Która frakcja skrobi odpowiada głównie za kleistość ryżu japońskiego?', 'Która frakcja skrobi odpowiada głównie za kleistość ryżu japońskiego?', 'ktora frakcja skrobi odpowiada glownie za kleistosc ryzu japonskiego?');
INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_002', 'explain_process', 'Wyjaśnij, dlaczego ryż do sushi twardnieje, gdy trafi do lodówki, i dlaczego nie da się tego w pełni „cofnąć” zwykłym przemieszaniem.', 'Retrogradacja skrobi: w niskiej temperaturze łańcuchy skrobi (zwłaszcza amylozy) porządkują się w struktury krystaliczne i wypychają wodę — ziarna twardnieją i matowieją. Proces przyspiesza w temperaturach chłodniczych. Odwrócenie wymaga ponownego podgrzania z wilgocią, a to zmienia teksturę i zaprawę; przemieszanie nie rozbija struktury. Dlatego ryż trzyma się w temperaturze zbliżonej do ciała, przykryty.', 2, 'cat_ryz', 'les_ryz_v1_01', 'needs_verification', 'src_claude_academy_v1');
