INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_003', 'error_analysis', 'Nowy kucharz zgłasza, że ryż wyszedł papkowaty i klei się „z zewnątrz”, a ziarna są popękane. Wskaż najbardziej prawdopodobne przyczyny i co sprawdzisz w pierwszej kolejności.', 'Prawdopodobne przyczyny: niedokładne płukanie (powierzchniowa skrobia zagęszcza wodę), za dużo wody, zbyt długie gotowanie lub zbyt intensywne mieszanie/ugniatanie przy zaprawianiu. Sprawdź: czy woda po płukaniu była klarowna, proporcję ryżu do wody i odmierzanie, czas gotowania, technikę mieszania (ruch tnący, nie ugniatanie).', 2, 'cat_ryz', 'les_ryz_v1_01', 'needs_verification', 'src_claude_academy_v1');
