INSERT INTO search_index (entity_type, entity_id, owner_id, title, body, folded) VALUES ('question', 'q_v1_003', NULL, 'Nowy kucharz zgłasza, że ryż wyszedł papkowaty i klei się „z zewnątrz”, a ziarna są popękane. Wskaż najbardziej prawdopodobne przyczyny i co sprawdzisz w pierws', 'Nowy kucharz zgłasza, że ryż wyszedł papkowaty i klei się „z zewnątrz”, a ziarna są popękane. Wskaż najbardziej prawdopodobne przyczyny i co sprawdzisz w pierwszej kolejności.', 'nowy kucharz zglasza, ze ryz wyszedl papkowaty i klei sie „z zewnatrz”, a ziarna sa popekane. wskaz najbardziej prawdopodobne przyczyny i co sprawdzisz w pierwszej kolejnosci.');
INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_004', 'fill_composition', 'Wymień składniki typowej zaprawy do ryżu do sushi (sushi-zu).', 'Ocet ryżowy, cukier, sól. Proporcje są częścią standardu lokalu.', 1, 'cat_ryz', 'les_ryz_v1_01', 'needs_verification', 'src_claude_academy_v1');
