INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_005', 'scenario', 'W połowie wieczornego serwisu zauważasz, że ryż na stanowisku stał się twardy i matowy, choć był przygotowany 40 minut temu. Co robisz teraz i co zmieniasz na przyszłość?', 'Teraz: nie używać ryżu o złej teksturze w produktach; przygotować nową porcję (lub użyć zapasowej), zgłosić straty. Diagnoza: zbyt niska temperatura przechowywania (np. przeciąg, zimny pojemnik), brak przykrycia (wysychanie) — retrogradacja i utrata wilgoci. Na przyszłość: właściwy pojemnik utrzymujący temperaturę, przykrycie wilgotną ściereczką/pokrywą, mniejsze partie gotowane częściej, kontrola czasu i temperatury zgodnie z procedurą.', 3, 'cat_ryz', 'les_ryz_v1_01', 'needs_verification', 'src_claude_academy_v1');
