INSERT INTO search_index (entity_type, entity_id, owner_id, title, body, folded) VALUES ('question', 'q_v1_005', NULL, 'W połowie wieczornego serwisu zauważasz, że ryż na stanowisku stał się twardy i matowy, choć był przygotowany 40 minut temu. Co robisz teraz i co zmieniasz na p', 'W połowie wieczornego serwisu zauważasz, że ryż na stanowisku stał się twardy i matowy, choć był przygotowany 40 minut temu. Co robisz teraz i co zmieniasz na przyszłość?', 'w polowie wieczornego serwisu zauwazasz, ze ryz na stanowisku stal sie twardy i matowy, choc byl przygotowany 40 minut temu. co robisz teraz i co zmieniasz na przyszlosc?');
INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_006', 'explain_process', 'Wyjaśnij, dlaczego nori w rolce robi się gumowate, jeśli rolka długo czeka na podanie.', 'Nori jest higroskopijne: chłonie wodę z wilgotnego ryżu i z powietrza. Wzrost zawartości wody zmienia strukturę z kruchej na elastyczną (uplastycznienie), więc arkusz staje się ciągnący i trudny do odgryzienia. Im dłużej rolka czeka, tym więcej wilgoci przechodzi do nori.', 2, 'cat_nori', 'les_nori_v1_01', 'needs_verification', 'src_claude_academy_v1');
