INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_007', 'multi', 'Które działania ograniczają wchłanianie wilgoci przez nori na stanowisku? Zaznacz wszystkie poprawne.', 'Szczelne zamykanie opakowania, trzymanie z dala od pary i źródeł wilgoci oraz wyjmowanie tylko potrzebnej liczby arkuszy ograniczają wilgoć. Trzymanie otwartego opakowania przy garnku z ryżem i przechowywanie w lodówce bez szczelnego opakowania zwiększają wilgoć (para, skraplanie).', 1, 'cat_nori', 'les_nori_v1_01', 'needs_verification', 'src_claude_academy_v1');
