INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_008', 'single', 'Którą stroną nori zwykle kładzie się do ryżu?', 'Zwyczajowo stroną matową (bardziej szorstką) — ryż lepiej się jej trzyma, a błyszcząca strona jest na zewnątrz. Standard lokalu może to doprecyzować.', 1, 'cat_nori', 'les_nori_v1_01', 'needs_verification', 'src_claude_academy_v1');
