INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_009', 'error_analysis', 'Przy zwijaniu futomaki nori pęka wzdłuż. Podaj możliwe przyczyny i sposób zapobiegania.', 'Przyczyny: arkusz przesuszony/kruchy, zbyt duże napięcie przy zwijaniu, za gruba warstwa ryżu lub zbyt dużo farszu w stosunku do arkusza, ryż rozłożony aż do krawędzi bez zostawienia marginesu. Zapobieganie: odpowiednia ilość ryżu i farszu wg standardu, margines na zamknięcie, równomierny docisk, użycie arkusza we właściwej kondycji.', 2, 'cat_nori', 'les_nori_v1_01', 'needs_verification', 'src_claude_academy_v1');
