INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_010', 'compare', 'Porównaj nori świeżo wyjęte ze szczelnego opakowania i nori, które leżało 45 minut otwarte na stanowisku obok ryżu. Jak różnią się teksturą i dlaczego?', 'Świeże: kruche, lekko chrupiące, łatwo się odgryza. Leżące: miękkie, elastyczne, gumowate, ciągnie się. Przyczyna: higroskopijność — chłonięcie pary wodnej z otoczenia i od ryżu; woda działa jak plastyfikator struktury arkusza.', 2, 'cat_nori', 'les_nori_v1_01', 'needs_verification', 'src_claude_academy_v1');
