INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_011', 'single', 'Który z wymienionych zabiegów skutecznie unieszkodliwia larwy Anisakis w rybie przeznaczonej do spożycia na surowo?', 'Odpowiednie mrożenie (np. ≤ −20 °C we wszystkich częściach przez co najmniej 24 h lub ≤ −35 °C przez co najmniej 15 h). Zaprawa octowa, sos sojowy ani wasabi nie zabijają larw.', 1, 'cat_higiena', 'les_higiena_v1_01', 'needs_verification', 'src_claude_academy_v1');
