INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_012', 'explain_process', 'Dlaczego histaminy w tuńczyku nie da się usunąć przez zamrożenie ani gotowanie i co z tego wynika dla pracy na stanowisku?', 'Histamina powstaje z histydyny pod wpływem enzymów bakterii, gdy ryba jest za ciepła. Jest substancją odporną na temperaturę — mrożenie zatrzymuje bakterie, ale nie rozkłada już powstałej histaminy, a gotowanie jej nie niszczy. Wniosek: jedyną ochroną jest nieprzerwany łańcuch chłodniczy — krótkie pobieranie z chłodni, małe porcje na stanowisku, kontrola temperatur i odrzucanie podejrzanego surowca.', 3, 'cat_higiena', 'les_higiena_v1_01', 'needs_verification', 'src_claude_academy_v1');
