INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_013', 'error_analysis', 'Kucharz rozmraża łososia na blacie w temperaturze kuchni, „bo w chłodni trwa to za długo”. Oceń tę praktykę.', 'Błąd: powierzchnia ryby długo przebywa w temperaturze sprzyjającej namnażaniu bakterii, podczas gdy środek jest jeszcze zamrożony; rośnie ryzyko mikrobiologiczne i (u niektórych gatunków) powstawania histaminy, pogarsza się tekstura i wyciek. Poprawnie: rozmrażać w chłodni (0–4 °C) z wyprzedzeniem zaplanowanym w produkcji, nie zamrażać ponownie.', 2, 'cat_higiena', 'les_higiena_v1_01', 'needs_verification', 'src_claude_academy_v1');
