INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_014', 'multi', 'Które sygnały powinny wykluczyć rybę z użycia do sushi? Zaznacz wszystkie poprawne.', 'Zapach amoniakalny/kwaśny, oślizgła powierzchnia i utrata sprężystości są sygnałami zepsucia. Lekki zapach morza i jędrne mięso są cechami świeżej ryby.', 1, 'cat_higiena', 'les_higiena_v1_01', 'needs_verification', 'src_claude_academy_v1');
