INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_015', 'scenario', 'Dostawa tuńczyka przyjechała, a termometr pokazuje w środku produktu temperaturę wyraźnie wyższą niż wymagana przy przyjęciu. Dostawca mówi, że „to tylko chwila w drodze”. Co robisz?', 'Nie przyjmować towaru niezgodnego z wymaganiami temperatury (zgodnie z procedurą przyjęcia dostaw), udokumentować pomiar, zgłosić przełożonemu/osobie odpowiedzialnej i dostawcy. Uzasadnienie: przerwanie łańcucha chłodniczego u tuńczyka grozi powstaniem histaminy, której nie usuwa późniejsze schłodzenie ani mrożenie — ryzyko jest niewidoczne i nieodwracalne.', 3, 'cat_higiena', 'les_higiena_v1_01', 'needs_verification', 'src_claude_academy_v1');
