INSERT INTO search_index (entity_type, entity_id, owner_id, title, body, folded) VALUES ('question', 'q_v1_015', NULL, 'Dostawa tuńczyka przyjechała, a termometr pokazuje w środku produktu temperaturę wyraźnie wyższą niż wymagana przy przyjęciu. Dostawca mówi, że „to tylko chwila', 'Dostawa tuńczyka przyjechała, a termometr pokazuje w środku produktu temperaturę wyraźnie wyższą niż wymagana przy przyjęciu. Dostawca mówi, że „to tylko chwila w drodze”. Co robisz?', 'dostawa tunczyka przyjechala, a termometr pokazuje w srodku produktu temperature wyraznie wyzsza niz wymagana przy przyjeciu. dostawca mowi, ze „to tylko chwila w drodze”. co robisz?');
INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_016', 'explain_process', 'Dlaczego ciasto do tempury miesza się krótko i zostawia się w nim grudki?', 'Krótkie mieszanie ogranicza tworzenie sieci glutenowej z białek mąki pszennej (gliadyn i glutenin). Rozwinięty gluten daje po smażeniu twardą, ciągnącą skorupkę. Grudki świadczą o niewyrobionym glutenie i sprzyjają lekkiej, nieregularnej, kruchej strukturze.', 2, 'cat_panierki', 'les_panierki_v1_01', 'needs_verification', 'src_claude_academy_v1');
