INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_017', 'error_analysis', 'Tempura wychodzi blada, ciężka i nasiąknięta olejem. Co najpewniej jest nie tak?', 'Najczęściej za niska temperatura oleju — skorupka nie zastyga szybko, woda odparowuje powoli, olej wnika do produktu. Przyczyną bywa też przeładowanie frytownicy (spadek temperatury) lub zbyt gęste ciasto. Rozwiązanie: kontrola temperatury termometrem, smażenie mniejszymi partiami, odzyskanie temperatury między partiami.', 2, 'cat_panierki', 'les_panierki_v1_01', 'needs_verification', 'src_claude_academy_v1');
