INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_018', 'single', 'Jaki jest główny powód używania bardzo zimnej wody do ciasta tempura?', 'Zimna woda spowalnia rozwój glutenu (i pęcznienie skrobi), dzięki czemu skorupka jest krucha; dodatkowo duża różnica temperatur z olejem sprzyja gwałtownemu odparowaniu i lekkiej strukturze.', 1, 'cat_panierki', 'les_panierki_v1_01', 'needs_verification', 'src_claude_academy_v1');
