INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_019', 'match', 'Dopasuj błąd do jego najbardziej prawdopodobnej przyczyny.', 'Nasiąknięcie olejem — za zimny olej; twarda skorupka — przemieszane ciasto (gluten); ciasto odpada od produktu — mokra powierzchnia produktu; ciemna skorupka przy surowym środku — za gorący olej.', 2, 'cat_panierki', 'les_panierki_v1_01', 'needs_verification', 'src_claude_academy_v1');
