INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_020', 'compare', 'Porównaj panierkę panko i ciasto tempura: strukturę, sposób nakładania i efekt po usmażeniu.', 'Panko: płatki porowatego pieczywa, nakładane zwykle po mące i jajku (panierowanie trzystopniowe); daje grubszą, bardzo chrupiącą, nieregularną warstwę. Tempura: płynne ciasto z mąki o niskiej zawartości białka/skrobi i zimnej wody, krótko mieszane; daje cienką, lekką, delikatnie chrupiącą skorupkę. Tempura szybciej traci chrupkość i wymaga natychmiastowego podania.', 2, 'cat_panierki', 'les_panierki_v1_01', 'needs_verification', 'src_claude_academy_v1');
