INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_021', 'explain_process', 'Wyjaśnij, co utrzymuje majonez w stanie emulsji i dlaczego zbyt szybkie dodanie oleju na początku powoduje jego zwarzenie.', 'Majonez to emulsja oleju w fazie wodnej stabilizowana emulgatorem — głównie lecytyną z żółtka, której cząsteczki otaczają kropelki oleju (część hydrofilowa do wody, lipofilowa do tłuszczu). Na początku fazy wodnej i emulgatora jest mało, więc szybko wlany olej tworzy duże krople, których emulgator nie zdąży otoczyć — krople łączą się i faza olejowa się oddziela.', 2, 'cat_sosy', 'les_sosy_v1_01', 'needs_verification', 'src_claude_academy_v1');
