INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_022', 'single', 'Który składnik żółtka jest głównym emulgatorem w majonezie?', 'Lecytyna (fosfolipid) — ma część hydrofilową i lipofilową.', 1, 'cat_sosy', 'les_sosy_v1_01', 'needs_verification', 'src_claude_academy_v1');
