INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_023', 'error_analysis', 'Glazura na bazie sosu sojowego, cukru i mirinu wyszła ciemna i gorzka. Wyjaśnij mechanizm i jak zapobiec temu w przyszłości.', 'Przegrzanie podczas redukcji: wraz z odparowaniem wody rośnie stężenie cukrów, temperatura sosu rośnie, cukry karmelizują się i przypalają, a reakcje Maillarda zachodzą zbyt intensywnie — powstaje gorycz. Zapobieganie: mniejszy ogień pod koniec redukcji, mieszanie, kontrola gęstości (próbka schłodzona na talerzyku), stała receptura i czas.', 3, 'cat_sosy', 'les_sosy_v1_01', 'needs_verification', 'src_claude_academy_v1');
