INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_024', 'scenario', 'Przed serwisem okazuje się, że pikantny sos kremowy w butelce się rozwarstwił. Co robisz, żeby nie stracić całej partii, i co sprawdzasz, żeby problem się nie powtórzył?', 'Ratunek: przenieść do miski, dodać nową bazę z emulgatorem (np. żółtko lub niewielką ilość majonezu) i stopniowo wmiksować zwarzony sos; sprawdzić smak i konsystencję. Jeśli są wątpliwości co do bezpieczeństwa (czas, temperatura) — nie ratować, wyrzucić zgodnie z procedurą. Przyczyny do sprawdzenia: zbyt szybkie dodanie płynnych dodatków (ostry sos, sok), proporcje niezgodne z recepturą, przechowywanie w zbyt zimnym/ciepłym miejscu, zbyt długie przechowywanie.', 3, 'cat_sosy', 'les_sosy_v1_01', 'needs_verification', 'src_claude_academy_v1');
