INSERT INTO search_index (entity_type, entity_id, owner_id, title, body, folded) VALUES ('question', 'q_v1_024', NULL, 'Przed serwisem okazuje się, że pikantny sos kremowy w butelce się rozwarstwił. Co robisz, żeby nie stracić całej partii, i co sprawdzasz, żeby problem się nie p', 'Przed serwisem okazuje się, że pikantny sos kremowy w butelce się rozwarstwił. Co robisz, żeby nie stracić całej partii, i co sprawdzasz, żeby problem się nie powtórzył?', 'przed serwisem okazuje sie, ze pikantny sos kremowy w butelce sie rozwarstwil. co robisz, zeby nie stracic calej partii, i co sprawdzasz, zeby problem sie nie powtorzyl?');
INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_025', 'single', 'Dlaczego gęstość glazury należy oceniać w temperaturze podania, a nie tylko na gorąco?', 'Lepkość roztworów cukru silnie zależy od temperatury — na gorąco sos jest rzadszy, po schłodzeniu gęstnieje. Ocena tylko na gorąco prowadzi do zbyt gęstej glazury po ostygnięciu.', 2, 'cat_sosy', 'les_sosy_v1_01', 'needs_verification', 'src_claude_academy_v1');
