INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_026', 'explain_process', 'Wyjaśnij, dlaczego zasada FIFO nie działa bez etykietowania i co musi zawierać dobra etykieta.', 'FIFO wymaga wiedzy, który produkt jest starszy; bez etykiety nie da się tego ustalić, a pojemniki mieszają się przy uzupełnianiu. Etykieta: nazwa produktu, data i godzina przygotowania/otwarcia, data/godzina przydatności (wg procedury), osoba przygotowująca. Nowe porcje stawia się za starszymi.', 2, 'cat_jakosc', 'les_jakosc_v1_01', 'needs_verification', 'src_claude_academy_v1');
