INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_027', 'scenario', 'Kierownik zauważa, że ten sam produkt z karty wygląda różnie zależnie od zmiany, a koszt ryby rośnie. Jakie działania wprowadzisz jako kucharz odpowiedzialny za stanowisko?', 'Ustandaryzować: korzystać z karty technologicznej (gramatury, liczba kawałków, sposób krojenia), ważyć porcje ryżu i ryby, przygotować zdjęcie wzorcowe produktu przy stanowisku, przeszkolić zmianę i robić wyrywkową kontrolę wag. Uzasadnić kosztem: nadwyżka kilku gramów w każdej porcji sumuje się w znaczącą stratę.', 3, 'cat_jakosc', 'les_jakosc_v1_01', 'needs_verification', 'src_claude_academy_v1');
