INSERT INTO search_index (entity_type, entity_id, owner_id, title, body, folded) VALUES ('question', 'q_v1_027', NULL, 'Kierownik zauważa, że ten sam produkt z karty wygląda różnie zależnie od zmiany, a koszt ryby rośnie. Jakie działania wprowadzisz jako kucharz odpowiedzialny za', 'Kierownik zauważa, że ten sam produkt z karty wygląda różnie zależnie od zmiany, a koszt ryby rośnie. Jakie działania wprowadzisz jako kucharz odpowiedzialny za stanowisko?', 'kierownik zauwaza, ze ten sam produkt z karty wyglada roznie zaleznie od zmiany, a koszt ryby rosnie. jakie dzialania wprowadzisz jako kucharz odpowiedzialny za stanowisko?');
INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_028', 'multi', 'Co sprawdzasz w kontroli wizualnej rolki przed wydaniem? Zaznacz wszystkie poprawne.', 'Równe kawałki, czyste krawędzie cięcia, szczelne zamknięcie rolki i zgodność z zamówieniem/alergenami to elementy kontroli. Temperatura pomieszczenia magazynu nie jest elementem kontroli konkretnego talerza przed wydaniem.', 1, 'cat_jakosc', 'les_jakosc_v1_01', 'needs_verification', 'src_claude_academy_v1');
