INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_029', 'error_analysis', 'Rolki po pokrojeniu mają poszarpane krawędzie, a ryż się zgniata. Co jest najczęstszą przyczyną i jak ją usunąć?', 'Najczęściej tępy lub suchy, zabrudzony nóż (oraz cięcie naciskiem zamiast płynnym ruchem). Rozwiązanie: ostry nóż, przecieranie ostrza wilgotną ściereczką między cięciami, cięcie płynnym ruchem bez dociskania, właściwe zamknięcie i zagęszczenie rolki.', 2, 'cat_jakosc', 'les_jakosc_v1_01', 'needs_verification', 'src_claude_academy_v1');
