INSERT INTO search_index (entity_type, entity_id, owner_id, title, body, folded) VALUES ('question', 'q_v1_029', NULL, 'Rolki po pokrojeniu mają poszarpane krawędzie, a ryż się zgniata. Co jest najczęstszą przyczyną i jak ją usunąć?', 'Rolki po pokrojeniu mają poszarpane krawędzie, a ryż się zgniata. Co jest najczęstszą przyczyną i jak ją usunąć?', 'rolki po pokrojeniu maja poszarpane krawedzie, a ryz sie zgniata. co jest najczestsza przyczyna i jak ja usunac?');
INSERT OR IGNORE INTO questions (id, type, prompt, explanation, difficulty, category_id, lesson_id, status, source_id) VALUES ('q_v1_030', 'compare', 'Porównaj reżim przechowywania na stanowisku dla surowej ryby i dla ryżu do sushi. Dlaczego są różne?', 'Ryba: jak najzimniej (zakres chłodniczy wg procedury), małe porcje na stanowisku, szybki powrót do chłodni — ograniczenie wzrostu bakterii i powstawania histaminy. Ryż: ciepły (zbliżony do temperatury ciała), przykryty, z limitem czasu — w chłodzie twardnieje (retrogradacja), a zakwaszenie zaprawą częściowo ogranicza ryzyko mikrobiologiczne. Różne cele: bezpieczeństwo ryby vs tekstura ryżu przy kontroli czasu.', 3, 'cat_jakosc', 'les_jakosc_v1_01', 'needs_verification', 'src_claude_academy_v1');
